"""Parsing readings from text."""
from readings import Reading


def _parse_line(line):
    sensor, level = line.split(",")
    return Reading(sensor.strip(), int(level))


def parse_readings(text):
    """Parse lines of 'sensor,level' into Reading records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out

